// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeCostQuoteNumericalTest {

	@Test
	void anOutputAlignedChunkBoundaryDoesNotAddASpuriousBuffer() {
		double rows = 200_762_397.84312364D;
		LmdbNativeCostQuote quote = bufferedQuote(rows);
		assertThat(quote.forSlice(768D).expected(Feature.INTERPRETED_ROW))
				.as("exactly three output buffers, without reconstructing demand through a rounded fraction")
				.isCloseTo(768D, within(1e-9D));
		assertThat(quote.forSlice(768D).expected(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(768D);
	}

	@Test
	void outputBuffersKeepConsumerMaterializationAndZeroDemandSeparate() {
		LmdbNativeCostQuote quote = bufferedQuote(512D);
		double[] slices = { 0D, 1D, 256D, 257D, 512D, 513D, -1D };
		double[] produced = { 0D, 256D, 256D, 512D, 512D, 512D, 512D };
		double[] consumed = { 0D, 1D, 256D, 257D, 512D, 512D, 512D };
		for (int i = 0; i < slices.length; i++) {
			LmdbNativeCostVector actual = quote.forSlice(slices[i]);
			assertThat(actual.expected(Feature.INTERPRETED_ROW)).as("producer for slice %s", slices[i])
					.isEqualTo(produced[i]);
			assertThat(actual.expected(Feature.OUTPUT_MATERIALIZATION)).as("consumer for slice %s", slices[i])
					.isEqualTo(consumed[i]);
			assertThat(actual.expected(Feature.OPEN)).isEqualTo(1D);
		}
	}

	@Test
	void unusableOutputEstimatesKeepTheirCompleteUnchunkedWork() {
		for (double rows : new double[] { Double.NaN, Double.POSITIVE_INFINITY, 0D, -1D }) {
			LmdbNativeCostQuote quote = new LmdbNativeCostQuote(LmdbNativeCostVector.point(Feature.OPEN, 1D),
					LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 512D), rows, false, false);
			assertThat(quote.forSlice(1D).expected(Feature.INTERPRETED_ROW)).as("unusable rows %s", rows)
					.isEqualTo(512D);
			assertThat(quote.forSlice(1D).expected(Feature.OUTPUT_MATERIALIZATION)).isZero();
		}
	}

	private static LmdbNativeCostQuote bufferedQuote(double rows) {
		return new LmdbNativeCostQuote(LmdbNativeCostVector.point(Feature.OPEN, 1D),
				LmdbNativeCostVector.zero(), rows, false, false,
				new LmdbNativeCostQuote.ChunkedWork(LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, rows),
						rows, 256));
	}

	@Test
	void aFiniteExactWorkCountDoesNotOverflowItsMidpoint() {
		LmdbNativeCostQuote quote = LmdbNativeCostQuote.ofWork(LmdbNativeWork.exact(Double.MAX_VALUE), 1D);
		assertThat(quote.total().low(Feature.SCANNED_ROW)).isEqualTo(Double.MAX_VALUE);
		assertThat(quote.total().expected(Feature.SCANNED_ROW)).isEqualTo(Double.MAX_VALUE);
		assertThat(quote.total().high(Feature.SCANNED_ROW)).isEqualTo(Double.MAX_VALUE);
	}

	@Test
	void aLargeFiniteIntervalKeepsItsExpectedCountBetweenItsBounds() {
		double low = Double.MAX_VALUE * 0.75D;
		double high = Double.MAX_VALUE;
		LmdbNativeCostQuote quote = LmdbNativeCostQuote.ofWork(LmdbNativeWork.between(low, high), 1D);
		assertThat(quote.total().expected(Feature.SCANNED_ROW)).isEqualTo(low + (high - low) / 2D);
		assertThat(quote.total().low(Feature.SCANNED_ROW)).isEqualTo(low);
		assertThat(quote.total().high(Feature.SCANNED_ROW)).isEqualTo(high);
	}

	@Test
	void anUnknownCeilingCannotFallBelowItsProvenLargeFloor() {
		double low = 2e15D; // A finite floor above the former magnitude sentinel.
		LmdbNativeCostQuote quote = LmdbNativeCostQuote.ofWork(LmdbNativeWork.atLeast(low), 1D);
		assertThat(quote.total().low(Feature.SCANNED_ROW)).isEqualTo(low);
		assertThat(quote.total().expected(Feature.SCANNED_ROW)).isEqualTo(low);
		assertThat(quote.total().high(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(low);
		assertThat(quote.bounded()).isFalse();
	}

	@Test
	void overflowedWorkRemainsExpensiveAndUnboundedInsteadOfBreakingAdmission() {
		LmdbNativeWork overflowed = LmdbNativeWork.exact(Double.MAX_VALUE)
				.plus(LmdbNativeWork.exact(Double.MAX_VALUE));
		assertThat(overflowed.low()).isPositive().isInfinite();
		LmdbNativeCostQuote quote = LmdbNativeCostQuote.ofWork(overflowed, 1D);
		assertThat(quote.total().expected(Feature.SCANNED_ROW)).isEqualTo(Double.MAX_VALUE);
		assertThat(quote.total().high(Feature.SCANNED_ROW)).isPositive().isInfinite();
		assertThat(quote.bounded()).isFalse();
	}
}
